const EXACT = new Map(PAIRS);
const PHRASES = [...PAIRS].filter(([vi]) => vi.length >= 6).sort((a, b) => b[0].length - a[0].length);

export function lang(): Lang {
  if (typeof localStorage === "undefined") return "vi";
  return localStorage.getItem(KEY) === "en" ? "en" : "vi";
}

export function setLang(next: Lang) {
  localStorage.setItem(KEY, next);
  for (const hear of listeners) hear(next);
}

export function tr(text: string): string {
  if (!text || lang() !== "en") return text;
  const hit = EXACT.get(text);
  if (hit) return hit;
  let out = text;
  for (const [vi, en] of PHRASES) {
    if (vi && out.includes(vi)) out = out.split(vi).join(en);
  }
  return out;
}

export function useLang(): Lang {
  const [now, setNow] = useState<Lang>("vi");
  useEffect(() => {
    setNow(lang());
    listeners.add(setNow);
    return () => {
      listeners.delete(setNow);
    };
  }, []);
  return now;
}
